INSERT INTO public.libro (libro_id, titulo, autor, genero, descripcion, portada_url, nivel_educativo, calificacion_promedio, activo, pagina_actual, paginas_totales) VALUES (4, 'Cien años de soledad', 'Gabriel García Márquez', 'Novela', null, 'https://www.rae.es/sites/default/files/portada_cien_anos_de_soledad_0.jpg', 'Superior', 4.67, true, 0, 100), (5, 'El principito', 'Antoine de Saint-Exupéry', 'Fábula', 'Cuenta la historia de un piloto varado en el desierto que encuentra a un niño, el Principito, proveniente de otro asteroide. El libro combina una narrativa poética con ilustraciones propias del autor para explorar temas filosóficos como el amor, la amistad, la pérdida, la muerte y el sentido de la vida, a través de una crítica a la perspectiva adulta', 'https://cdn.prod.website-files.com/6034d7d1f3e0f52c50b2adee/681b63dd7d9dbb4c4ce5ae76_WJlUnXLgNrZqh3HN_u7WMEnTVs1tV0qKwtUkvXJ2JTk.jpeg', 'Básico', 5, true, 0, 100), (6, '1984', 'George Orwell', 'Ficción', 'es un libro', 'https://acdn-us.mitiendanube.com/stores/004/088/117/products/569813-cedaf5cd715a2c721d17273678784297-1024-1024.jpg', 'Básico', null, true, 0, 100), (9, 'La gran ocasión', 'Montes Graciela', 'Novela', 'La especialista y escritora argentina Graciela Montes reflexiona acerca de la lectura. El lector, se va volviendo más astuto en la búsqueda de indicios, más libre en pensamiento, más ágil en puntos de vista, más ancho en horizontes, dueño de un universo de significaciones más rico, más resistente y de tramas más sutiles. Lectura a lectura, se va construyendo su lugar en el mundo.', 'https://buenosaires.gob.ar/sites/default/files/media/image/2021/03/27/91e6ed445a86ed17dbcce18f8e317d3e5ea41e11.jpg', 'Básico', 3.81, true, 0, 100), (10, 'Los ojos del perro Siberiano', 'Antonio Santa Ana', 'Novela', 'Es la Historia de un adolescente que descubre que su hermano padece VIH', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ3t0F5xVwGmA6J3m_O0b-yamLPvZSEoKUEVg&s', 'Básico', 3.33, true, 0, 100), (12, 'Don Quijote de la Mancha', 'Miguel de Cervantes Saavedra', 'Novela', 'Considerada una de las obras más importantes de la literatura universal. Narra las aventuras del ingenioso hidalgo Don Quijote y su fiel escudero Sancho Panza, explorando los límites entre la realidad y la fantasía.', 'https://www.planetadelibros.cl/usuaris/libros/thumbs/c71e8c1a-f520-4bb3-9fee-a592585ba8b0/d_1200_1200/379580_portada_don-quijote-de-la-mancha-comic_miguel-de-cervantes_202310231106.webp', 'Superior', 3.75, true, 0, 100), (13, 'Rebelion en la granja', 'George Orwell', 'Novela', 'Orientado a estudiantes de sexto a;o.', 'https://colegiolospensamientos.cl/wp-content/uploads/2024/04/Mayo-IV%C2%B0M.-La-rebelion-en-la-granja-George-Orwell-200x300.jpg', 'Superior', 4.2, true, 0, 100), (14, 'Martín Fierro', 'José Hernández', 'Poesía', 'Poema épico nacional argentino que relata las desventuras de un gaucho injustamente reclutado, símbolo de la libertad y la identidad nacional.', 'https://www.argentina.gob.ar/sites/default/files/martin-fierro-34534sf-8.jpg', 'Superior', 3.88, true, 0, 100), (15, 'Rayuela', 'Julio Cortázar', 'Novela', 'Obra fundamental del boom latinoamericano. Propone una lectura no lineal y experimental sobre el amor, la búsqueda existencial y la vida bohemia en París.', 'https://upload.wikimedia.org/wikipedia/commons/c/ca/Rayuela_JC.png', 'Superior', 3.89, true, 0, 100), (16, 'La casa de los espíritus', 'Isabel Allende', 'Realismo mágico', 'Sigue a la familia Trueba a lo largo de generaciones, combinando historia política chilena con elementos mágicos y emocionales.', 'https://images.cdn2.buscalibre.com/fit-in/360x360/f6/48/f648c86c1bd999355234c41ff527954e.jpg', 'Superior', 2.83, true, 0, 100), (17, 'Rosaura a las diez', 'Marco Denevi', 'Policial', 'Novela policial psicológica argentina que se desarrolla en una pensión. El relato se reconstruye a partir de diferentes versiones de los hechos.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSW24ZQV2N-jHaP041EelwjGJF3iox5_HpaRQ&s', 'Superior', 4.67, true, 0, 100), (18, 'Crónica de una muerte anunciada', 'Gabriel García Márquez', 'Novela', 'Narra el asesinato de Santiago Nasar a través de múltiples voces, donde todos saben lo que va a ocurrir, menos la víctima.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRBB864HsyzicB97xFq5mb1FSzaRiatzGNe_g&s', 'Superior', 4.75, true, 0, 100), (19, 'Antígona Vélez', 'Leopoldo Marechal', 'Teatro', 'Versión argentina de la tragedia de Sófocles, ambientada en la época de la Conquista del Desierto, que combina mitología y crítica social.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSaWbHTxv1w4MZrJapU3FTZLt6KYDcazIi02A&s', 'Superior', 3.67, true, 0, 100), (20, 'El túnel', 'Ernesto Sabato', 'Novela psicológica', 'Cuenta la historia de un pintor obsesionado con una mujer. Reflexiona sobre la soledad, la incomunicación y la alienación.', 'https://palabrasylogos.odiseus.org/files/2013/06/EL-TUNEL-PORTADA.jpg', 'Superior', 2, true, 0, 100), (21, 'Juvenilia', 'Miguel Cané', 'Memorias', 'Recoge recuerdos de juventud del autor en el Colegio Nacional de Buenos Aires, mostrando la vida escolar y política de la época.', 'https://colihue.com.ar/wp-content/uploads/2022/11/COLCI-101037-69789505810376.jpg', 'Superior', 2.67, true, 0, 100), (22, 'Los tres mosqueteros', 'Alejandro Dumas', 'Novela', 'Novela clásica: las aventuras de DArtagnan y los tres mosqueteros al servicio del rey Luis XIII.', 'https://covers.openlibrary.org/b/id/8088264-L.jpg', 'Medio', null, true, 0, 100), (23, 'Los tres mosqueteros', 'Alejandro Dumas', 'Novela', 'Novela clásica: las aventuras de DArtagnan y los tres mosqueteros al servicio del rey Luis XIII.', 'https://covers.openlibrary.org/b/id/8088264-L.jpg', 'Medio', null, true, 0, 100), (24, 'Los tres mosqueteros', 'Alejandro Dumas', 'Novela', 'Novela clásica: las aventuras de DArtagnan y los tres mosqueteros al servicio del rey Luis XIII.', 'https://covers.openlibrary.org/b/id/8088264-L.jpg', 'Medio', null, true, 0, 